    static func dimension(_ id: String) -> ClassificationDimension? { dimensions.first { $0.id == id } }
    static func terms(in dimension: String) -> [ClassificationTerm] { terms.filter { $0.dimension == dimension } }
    static func term(_ canonical: String, in dimension: String) -> ClassificationTerm? {
        terms.first { $0.dimension == dimension && $0.canonical == canonical }
    }
    static func allowsMultiple(_ id: String) -> Bool { dimensions.first { $0.id == id }?.allowsMultiple ?? true }
    static var termCount: Int { terms.count }
    static var recommendedCount: Int { terms.filter { $0.status == "推荐" }.count }
